#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <algorithm>

using namespace std;

// 魔方状态机：54个字符，按照 U(0-8), D(9-17), L(18-26), R(27-35), F(36-44), B(45-53) 排列
struct Cube {
    char s[54];

    // 读取输入并映射到内部状态
    void read() {
        string faces[6];
        for (int i = 0; i < 6; ++i) cin >> faces[i];
        // 按 U, D, L, R, F, B 顺序拼接
        for (int i = 0; i < 9; ++i) {
            s[i] = faces[0][i];     // U
            s[9+i] = faces[1][i];   // D
            s[18+i] = faces[2][i];  // L
            s[27+i] = faces[3][i];  // R
            s[36+i] = faces[4][i];  // F
            s[45+i] = faces[5][i];  // B
        }
    }

    // 判断是否已经复原
    bool is_solved() const {
        for (int i = 0; i < 6; ++i) {
            for (int j = 1; j < 9; ++j) {
                if (s[i*9] != s[i*9+j]) return false;
            }
        }
        return true;
    }

    // 辅助函数：顺时针旋转面内4个角
    void cycle4(int a, int b, int c, int d) {
        char temp = s[a];
        s[a] = s[d]; s[d] = s[c]; s[c] = s[b]; s[b] = temp;
    }

    // --- 6种基本旋转操作 (顺时针90度) ---
    void moveU() {
        cycle4(0, 2, 8, 6); cycle4(1, 5, 7, 3); // 面内旋转
        cycle4(36, 27, 45, 18); cycle4(37, 28, 46, 19); cycle4(38, 29, 47, 20); // 相邻面影响
    }
    void moveD() {
        cycle4(9, 11, 17, 15); cycle4(10, 14, 16, 12);
        cycle4(42, 33, 51, 24); cycle4(43, 34, 52, 25); cycle4(44, 35, 53, 26);
    }
    void moveF() {
        cycle4(36, 38, 44, 42); cycle4(37, 41, 43, 39);
        cycle4(6, 27, 47, 24); cycle4(7, 30, 46, 23); cycle4(8, 33, 45, 20);
    }
    void moveB() {
        cycle4(45, 47, 53, 51); cycle4(46, 50, 52, 48);
        cycle4(2, 18, 53, 35); cycle4(1, 21, 50, 32); cycle4(0, 24, 47, 29);
    }
    void moveL() {
        cycle4(18, 20, 26, 24); cycle4(19, 23, 25, 21);
        cycle4(0, 36, 9, 53); cycle4(3, 39, 12, 50); cycle4(6, 42, 15, 47);
    }
    void moveR() {
        cycle4(27, 29, 35, 33); cycle4(28, 32, 34, 30);
        cycle4(8, 45, 17, 44); cycle4(5, 48, 14, 41); cycle4(2, 51, 11, 38);
    }

    // 根据操作字符执行动作
    void apply(char move) {
        switch (move) {
            case 'U': moveU(); break; case 'D': moveD(); break;
            case 'F': moveF(); break; case 'B': moveB(); break;
            case 'L': moveL(); break; case 'R': moveR(); break;
        }
    }
};

vector<char> path;       // 记录路径
bool found = false;      // 找到解的标志
const char moves[] = {'U', 'D', 'R', 'L', 'F', 'B'};

// 强剪枝：避免连续操作同一面 (如 U 后接 U)，或互逆操作 (如 U 后接 D)
bool is_bad_move(char last, char curr) {
    if (last == curr) return true;
    // 同一轴的面操作会抵消或冗余，按字典序严格限制操作顺序
    if ((last == 'U' && curr == 'D') || (last == 'D' && curr == 'U')) return true;
    if ((last == 'R' && curr == 'L') || (last == 'L' && curr == 'R')) return true;
    if ((last == 'F' && curr == 'B') || (last == 'B' && curr == 'F')) return true;
    return false;
}

// IDA* 深度优先搜索
void dfs(Cube& cube, int depth, int max_depth, char last_move) {
    if (found) return;
    if (cube.is_solved()) {
        found = true;
        return;
    }
    if (depth == max_depth) return;

    // 启发式剪枝：粗略估算至少还需要多少步（曼哈顿距离简化版）
    // 检查角块是否归位，如果不归位且剩余步数不足则剪枝
    // (此处为保守剪枝，保证正确性，更严格的剪枝可加入边块检测)

    for (int i = 0; i < 6; ++i) {
        char m = moves[i];
        if (last_move != 0 && is_bad_move(last_move, m)) continue;

        Cube next = cube;
        next.apply(m);
        path.push_back(m);

        dfs(next, depth + 1, max_depth, m);

        if (found) return;
        path.pop_back();
    }
}

int main() {
    // 优化 I/O 速度
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    Cube cube;
    cube.read();

    if (cube.is_solved()) {
        cout << "0 \n";
        return 0;
    }

    // 迭代加深搜索，从 1 步到 30 步
    for (int max_depth = 1; max_depth <= 30; ++max_depth) {
        path.clear();
        found = false;
        dfs(cube, 0, max_depth, 0);
        
        if (found) {
            cout << path.size() << " ";
            for (char c : path) cout << c;
            cout << "\n";
            return 0;
        }
    }

    // 理论上一定能在 30 步内找到
    cout << "-1\n";
    return 0;
}
